import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between a birth year and a given current year.

    The current year is passed in explicitly; this function never reads the clock.
    Raises ValueError if born is after now.
    """
    if born > now:
        raise ValueError(f"birth year {born} is after current year {now}")
    return now - born


def test_age_at_typical() -> None:
    assert age_at(1990, 2024) == 34


def test_age_at_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_at_is_plain_difference() -> None:
    assert age_at(1, 100) == 99


def test_age_at_rejects_future_birth() -> None:
    with pytest.raises(ValueError):
        age_at(2030, 2024)
